<pre class="snippet-code-js lang-js prettyprint-override"><code>class CustomClass {}

const namedFnExpression = function foo () { return 'foo'; };
const conciseMethod = ({ bar() { return 'bar'; } }).bar;

console.log('BigInt ...', {
  callable: isCallable(BigInt),
  function: isFunction(BigInt),
  constructSlot: hasConstructSlot(BigInt),
  newableFunction: isNewableFunction(BigInt),
  ownWritablePrototype: hasOwnWritablePrototype(BigInt),
  ownNonWritablePrototype: hasOwnNonWritablePrototype(BigInt),
  class: isClass(BigInt),
  builtInClass: isBuiltInClass(BigInt),
  customClass: isCustomClass(BigInt),
});

console.log('URL ...', {
  callable: isCallable(URL),
  function: isFunction(URL),
  constructSlot: hasConstructSlot(URL),
  newableFunction: isNewableFunction(URL),
  ownWritablePrototype: hasOwnWritablePrototype(URL),
  ownNonWritablePrototype: hasOwnNonWritablePrototype(URL),
  class: isClass(URL),
  builtInClass: isBuiltInClass(URL),
  customClass: isCustomClass(URL),
});

console.log('CustomClass ...', {
  callable: isCallable(CustomClass),
  function: isFunction(CustomClass),
  constructSlot: hasConstructSlot(CustomClass),
  newableFunction: isNewableFunction(CustomClass),
  ownWritablePrototype: hasOwnWritablePrototype(CustomClass),
  ownNonWritablePrototype: hasOwnNonWritablePrototype(CustomClass),
  class: isClass(CustomClass),
  builtInClass: isBuiltInClass(CustomClass),
  customClass: isCustomClass(CustomClass),
});

console.log('namedFnExpression ...', {
  callable: isCallable(namedFnExpression),
  function: isFunction(namedFnExpression),
  constructSlot: hasConstructSlot(namedFnExpression),
  newableFunction: isNewableFunction(namedFnExpression),
  ownWritablePrototype: hasOwnWritablePrototype(namedFnExpression),
  ownNonWritablePrototype: hasOwnNonWritablePrototype(namedFnExpression),
  class: isClass(namedFnExpression),
  builtInClass: isBuiltInClass(namedFnExpression),
  customClass: isCustomClass(namedFnExpression),
});

console.log('conciseMethod ...', {
  callable: isCallable(conciseMethod),
  function: isFunction(conciseMethod),
  constructSlot: hasConstructSlot(conciseMethod),
  newableFunction: isNewableFunction(conciseMethod),
  ownWritablePrototype: hasOwnWritablePrototype(conciseMethod),
  ownNonWritablePrototype: hasOwnNonWritablePrototype(conciseMethod),
  class: isClass(conciseMethod),
  builtInClass: isBuiltInClass(conciseMethod),
  customClass: isCustomClass(conciseMethod),
});

console.log('Math.max ...', {
  callable: isCallable(Math.max),
  function: isFunction(Math.max),
  constructSlot: hasConstructSlot(Math.max),
  newableFunction: isNewableFunction(Math.max),
  ownWritablePrototype: hasOwnWritablePrototype(Math.max),
  ownNonWritablePrototype: hasOwnNonWritablePrototype(Math.max),
  class: isClass(Math.max),
  builtInClass: isBuiltInClass(Math.max),
  customClass: isCustomClass(Math.max),
});

console.log('parseInt ...', {
  callable: isCallable(parseInt),
  function: isFunction(parseInt),
  constructSlot: hasConstructSlot(parseInt),
  newableFunction: isNewableFunction(parseInt),
  ownWritablePrototype: hasOwnWritablePrototype(parseInt),
  ownNonWritablePrototype: hasOwnNonWritablePrototype(parseInt),
  class: isClass(parseInt),
  builtInClass: isBuiltInClass(parseInt),
  customClass: isCustomClass(parseInt),
});</code></pre>
