<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script&gt;
const toFunctionString = Function.prototype.toString;

function getFunctionSource(value) {
  try {
    return toFunctionString.call(value).trim();
  } catch {
    return void 0;
  }
}

function isCallable(value) {
  return typeof value === 'function';
}
function isFunction(value) {
  try {
    return (
      isCallable(value) &amp;&amp;
      isCallable(value.bind) &amp;&amp;
      isCallable(value.call) &amp;&amp;
      isCallable(value.apply)
    );
  } catch {
    return false;
  }
}

function hasConstructSlot(value) {
  try {
    new /** @type {NewableFunction} */ (
      new Proxy(/** @type {object} */ (value), { construct: () =&gt; ({}) })
    )();
    return true;
  } catch {
    return false;
  }
}

function hasOwnWritablePrototype(value) {
  try {
    return Object.getOwnPropertyDescriptor(value, 'prototype')?.writable === true;
  } catch {
    return false;
  }
}
function hasOwnNonWritablePrototype(value) {
  try {
    return Object.getOwnPropertyDescriptor(value, 'prototype')?.writable === false;
  } catch {
    return false;
  }
}

function isNewableFunction(value) {
  return isFunction(value) &amp;&amp; hasConstructSlot(value);
}
function isClass(value) {
  return isNewableFunction(value) &amp;&amp; hasOwnNonWritablePrototype(value);
}

function isBuiltInClass(value) {
  return isClass(value) &amp;&amp; !(getFunctionSource(value) ?? '').startsWith('class');
}
function isCustomClass(value) {
  return isClass(value) &amp;&amp; (getFunctionSource(value) ?? '').startsWith('class');
}
&lt;/script&gt;</code></pre>
